import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Diagramme","description":"","frontmatter":{"title":"Diagramme","covers":{"screens":["SCR-021","SCR-067"],"stories":["US-074"]}},"headers":[],"relativePath":"de/usage/diagrams.md","filePath":"de/usage/diagrams.md"}`),a={name:`de/usage/diagrams.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="diagramme" tabindex="-1">Diagramme <a class="header-anchor" href="#diagramme" aria-label="Permalink to “Diagramme”">​</a></h1><p>Ein Diagramm modelliert einen Geschäftsprozess oder eine andere Sicht auf die Architektur mit der Notation eines <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>, zum Beispiel <em>Process Model (BPMN 2.0)</em>. Du legst Diagramme als Objekte an, findest, benennst um, löschst und stellst sie wieder her, und du platzierst die Elemente des Viewpoints auf der Zeichenfläche eines Diagramms.</p><p>Zum Ansehen brauchst du die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>). Anlegen, Umbenennen und Löschen braucht <code>entity:write</code>, Wiederherstellen <code>entity:restore</code> (Rolle <code>enterprise-architect</code>). Service-Accounts mit <code>entity:write</code> können Diagramme über die API wie Personen anlegen und ändern.</p><h2 id="diagramme-finden" tabindex="-1">Diagramme finden <a class="header-anchor" href="#diagramme-finden" aria-label="Permalink to “Diagramme finden”">​</a></h2><p>Du findest Diagramme an drei Stellen:</p><ul><li><strong>Die Seite <em>Diagramme</em>:</strong> Wähle in der Kopfzeile <em>Diagramme</em>. Die Seite listet die Diagramme nach Namen, unabhängig von Gross- und Kleinschreibung, jeweils mit ihrem Viewpoint, der Notation des Viewpoints und dem Zeitpunkt der letzten Änderung. Gib einen Namensteil in <em>Nach Name filtern</em> ein, um die Liste einzugrenzen; Zeichen wie <code>%</code> und <code>_</code> gelten, wie eingegeben. Die Liste zeigt 50 Diagramme auf einmal; wähle <em>Mehr laden</em> für die nächsten. Ohne Diagramm meldet die Seite <em>Noch keine Diagramme.</em></li><li><strong>Der Browser:</strong> Die Kategorie <em>Diagramme</em> unter <em>Aktueller Stand</em> in der Seitenleiste listet die Diagramme mit der Notation als kleiner Markierung (siehe <a href="./navigation#browser">Navigationsbaum</a>).</li><li><strong>Der Navigationsbaum:</strong> Diagramme, die in einen Ordner eingeordnet wurden (siehe <a href="./navigation#place-a-diagram">Diagramm einordnen</a>).</li></ul><p>Wähle ein Diagramm, um seine Seite zu öffnen.</p><h2 id="diagramm-anlegen" tabindex="-1">Diagramm anlegen <a class="header-anchor" href="#diagramm-anlegen" aria-label="Permalink to “Diagramm anlegen”">​</a></h2><ol><li><p>Wähle auf der Seite <em>Diagramme</em> <em>Diagramm anlegen</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>erforderlich, 1 bis 200 Zeichen; eindeutig unter den Diagrammen, unabhängig von Gross- und Kleinschreibung; umgebende Leerzeichen werden entfernt</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 2000 Zeichen</td></tr><tr><td>Viewpoint</td><td>erforderlich; der Viewpoint des Diagramms und seine Notation</td></tr></tbody></table></li><li><p>Wähle <em>Anlegen</em>. Das neue, leere Diagramm öffnet sich.</p></li></ol><p>Der Viewpoint wird beim Anlegen festgelegt und lässt sich später nicht ändern. Ist der Name vergeben, meldet der Dialog <em>Ein Diagramm mit diesem Namen gibt es schon.</em></p><h2 id="die-zeichenflache" tabindex="-1">Die Zeichenfläche <a class="header-anchor" href="#die-zeichenflache" aria-label="Permalink to “Die Zeichenfläche”">​</a></h2><p>Die Seite eines Diagramms zeigt Name, Beschreibung und Viewpoint und darunter die Zeichenfläche mit den Formen des Diagramms. Jede Form ist ein Kasten mit dem Namen der Entität, der Abkürzung ihres Typs und, falls der Viewpoint eine vorgibt, einem Rand in der Farbe ihres Typs. <strong>Eine Form ist eine Ansicht einer Entität: Die Entität selbst bleibt im Repository.</strong> Dieselbe Entität darf in einem Diagramm mehrfach vorkommen. Ein Diagramm zeigt nur Entitäten der Typen, die sein Viewpoint erlaubt. Notationsspezifische Formen, zum Beispiel die von BPMN, folgen in einer späteren Version; bis dahin ist jede Form ein Kasten.</p><p>Verschiebe die Zeichenfläche, indem du den Hintergrund ziehst, und zoome mit dem Mausrad oder mit den Schaltflächen <em>Vergrößern</em>, <em>Verkleinern</em> und <em>Ansicht einpassen</em> über der Zeichenfläche. Mit der Berechtigung <code>entity:read</code> kannst du das Diagramm so ansehen; die Zeichenfläche ist dann mit <em>Nur lesen</em> markiert und hat keine Palette, kein <em>Vorhandene hinzufügen</em> und kein <em>Speichern</em>.</p><p>Mit der Berechtigung <code>entity:write</code> bearbeitest du auch das Layout:</p><ul><li><strong>Neue Entität platzieren:</strong> Die Palette über der Zeichenfläche listet die Entitätstypen, die der Viewpoint erlaubt. Klicke einen Typ an, um eine neue Form in der Mitte der sichtbaren Zeichenfläche zu platzieren, oder ziehe den Typ auf die Zeichenfläche. Tippe den Namen in die neue Form und drücke Enter. Ohne Namen verschwindet die Form wieder (auch mit Escape). Die Form erhält die Standardgröße ihres Typs im Viewpoint in Punkt (pt); ohne gespeicherte Größe sind das 90 × 30 pt.</li><li><strong>Vorhandene Entität platzieren:</strong> <em>Vorhandene hinzufügen</em> öffnet eine Suche. Tippe einen Teil des Namens ein (ohne Unterscheidung von Groß- und Kleinschreibung; Zeichen wie <code>%</code> und <code>_</code> gelten, wie getippt) und wähle die Entität; <em>Mehr laden</em> zeigt weitere Treffer. Die Suche findet nur Entitäten der Typen, die der Viewpoint erlaubt. Die neue Form erscheint in der Mitte der sichtbaren Zeichenfläche.</li><li><strong>Verschieben und Größe ändern:</strong> Ziehe eine Form, und ziehe die Anfasser einer ausgewählten Form, um ihre Größe zu ändern. Mit der Tastatur wählst du eine Form (Tab oder Klick) und verschiebst sie mit den Pfeiltasten um 1 pt, mit Umschalt um 10 pt. Positionen liegen innerhalb von ±100 000 pt, Größen zwischen 1 und 2000 pt, jeweils mit höchstens zwei Nachkommastellen.</li><li><strong>Aus Diagramm entfernen:</strong> Wähle eine Form und dann <em>Aus Diagramm entfernen</em> über der Zeichenfläche, drücke Entf oder öffne mit der rechten Maustaste das Kontextmenü der Form. Die Form verschwindet aus dem Diagramm; <strong>die Entität bleibt im Repository.</strong></li><li><strong>Details einer Entität:</strong> Wähle eine Form, um ihre Details neben der Zeichenfläche zu öffnen (siehe <a href="#details-of-an-entity">Details einer Entität</a>).</li><li><strong>Speichern:</strong> <em>Speichern</em> sichert alle Änderungen in einem Schritt, auch die Änderungen von Entitäten in den Details. Bis dahin zeigt die Zeichenfläche <em>Ungespeicherte Änderungen</em>, und neue oder geänderte Formen tragen einen kleinen Punkt. Ein Diagramm enthält höchstens 2000 Formen, und ein Speichern legt höchstens 500 neue Entitäten an; die Zeichenfläche meldet, wenn eine Grenze erreicht ist.</li></ul><p>Verlässt du die Seite mit ungespeicherten Änderungen, fragt OEA, ob sie verworfen werden sollen. Hat jemand anderes (oder du in einem anderen Fenster) das Diagramm geändert, seit du es geöffnet hast, antwortet <em>Speichern</em> mit <em>Jemand anderes hat das Diagramm geändert</em>; wähle <em>Neu laden und meine Änderungen verwerfen</em>, um mit dem aktuellen Stand weiterzuarbeiten, oder <em>Weiter bearbeiten</em>, um deine Arbeit zuvor anderswo zu sichern. Auch das Umbenennen des Diagramms zählt als Änderung.</p><p>Lässt sich eine Form nicht speichern, zum Beispiel weil der Viewpoint ihren Typ nicht mehr erlaubt oder ihre Entität inzwischen gelöscht wurde, markiert die Zeichenfläche die Form mit dem Grund und behält alle deine Änderungen; gespeichert wird erst, wenn jede Form gültig ist.</p><h3 id="entitaten-mit-fehlenden-werten" tabindex="-1">Entitäten mit fehlenden Werten <a class="header-anchor" href="#entitaten-mit-fehlenden-werten" aria-label="Permalink to “Entitäten mit fehlenden Werten”">​</a></h3><p>Eine neue Entität von der Zeichenfläche hat nur einen Namen und einen Typ. Hat ihr Typ eine Pflichteigenschaft ohne Standardwert, wird die Entität trotzdem angelegt und gilt als <strong>unvollständig</strong>, bis der Wert geschrieben ist. Jede Form einer unvollständigen Entität zeigt <em>Unvollständig:</em> mit den Namen der fehlenden Eigenschaften. Andere Änderungen der Entität, zum Beispiel über die Batch-API, verlangen die Pflichtwerte weiterhin. Du vervollständigst die Entität in ihren Details (siehe unten) oder schreibst die Werte über die API (siehe <a href="./../api/">API-Referenz</a>).</p><p>Wird eine Entität gelöscht, sind ihre Formen im Diagramm ausgeblendet; sie erscheinen wieder, wenn die Entität wiederhergestellt wird.</p><h2 id="details-of-an-entity" tabindex="-1">Details einer Entität <a class="header-anchor" href="#details-of-an-entity" aria-label="Permalink to “Details einer Entität”">​</a></h2><p>Wähle eine Form, um das Detailfenster ihrer Entität neben der Zeichenfläche zu öffnen. Es zeigt Namen, Beschreibung, Typ und Version der Entität und für jede Eigenschaft ihres Typs ein Feld, in der Reihenfolge des Typs; eine Pflichteigenschaft ist markiert. Schließe das Fenster mit der Schaltfläche zum Schließen oder mit Escape; mit Tab gelangst du von der gewählten Form in das Fenster.</p><ul><li><strong>Lesen:</strong> Jede Person mit <code>entity:read</code> sieht die Werte. Einen Wert, den du nicht lesen darfst, zum Beispiel einen, der auf eine Rolle beschränkt ist, zeigt das Fenster als <em>Eingeschränkt</em>. Ohne <code>entity:write</code> ist das Fenster nur lesbar.</li><li><strong>Ändern:</strong> Mit <code>entity:write</code> änderst du den Namen, die Beschreibung und die Werte der Eigenschaften, die du schreiben darfst. Eine Eigenschaft, die auf eine Rolle beschränkt ist, die du nicht hast, zeigt ihren Wert ohne Eingabefeld. Bei einer Referenzeigenschaft suchst du die Entitäten des referenzierten Typs nach Namen. Eine leere Eingabe entfernt den Wert.</li><li><strong>Unvollständige Entität vervollständigen:</strong> Das Fenster nennt die fehlenden Pflichtwerte (<em>Pflichtwerte fehlen: …</em>). Trage sie ein und wähle <em>Speichern</em>; die Form verliert dann die Markierung <em>Unvollständig:</em>. Eine Pflichteigenschaft, die du nicht ändern darfst, bleibt Pflicht; die Entität bleibt unvollständig, bis jemand mit Schreibrecht sie schreibt.</li><li><strong>Speichern:</strong> Deine Änderungen in den Details zählen als ungespeicherte Änderungen des Diagramms, mit der Markierung <em>Ungespeicherte Änderungen</em>, und werden mit dem Layout durch <em>Speichern</em> in einem Schritt gesichert: Entweder wird alles gespeichert oder nichts. Ein Speichern ändert höchstens 500 Entitäten; die Zeichenfläche meldet, wenn die Grenze erreicht ist. Wer eine noch unvollständige Entität ändert, braucht ihre Pflichtwerte; vervollständige sie also im selben Schritt.</li><li><strong>Neue Entität:</strong> Auch die Details einer neuen Form nehmen eine Beschreibung und Werte auf; sie werden mit der Entität angelegt.</li></ul><p>Hat jemand anderes eine Entität geändert, seit du ihre Details geöffnet hast, antwortet <em>Speichern</em> mit <em>… wurde zwischenzeitlich von jemand anderem geändert</em> unter Nennung der Entität und speichert nichts. Deine Änderungen bleiben auf der Zeichenfläche; wähle <em>… neu laden und meine Änderungen daran verwerfen</em>, um die Entität erneut zu lesen (das verwirft nur deine Änderungen an dieser Entität), wiederhole dann deine Änderung und speichere erneut. Eine Entität mit offenen Punkten einer Lösung lässt sich nicht ändern; die Meldung nennt die Entität und ihre offenen Punkte, und deine Änderungen bleiben. Einen Wert, den der Server ablehnt, markiert das Fenster am Feld mit dem Grund.</p><h2 id="diagramm-umbenennen-und-loschen" tabindex="-1">Diagramm umbenennen und löschen <a class="header-anchor" href="#diagramm-umbenennen-und-loschen" aria-label="Permalink to “Diagramm umbenennen und löschen”">​</a></h2><p><em>Umbenennen</em> ändert Namen und Beschreibung eines Diagramms, auf der Seite <em>Diagramme</em> und auf der Seite des Diagramms. Hat jemand anderes das Diagramm inzwischen geändert, meldet der Dialog das; lade die Seite neu und wiederhole deine Änderung.</p><p><em>Löschen</em> fragt nach einer Bestätigung. Ein gelöschtes Diagramm erscheint nicht mehr in der Liste, im Browser und im Navigationsbaum, und sein Name kann wieder verwendet werden. <strong>Die Entitäten des Repositorys bleiben.</strong> Das Diagramm selbst lässt sich wiederherstellen (siehe unten).</p><h2 id="diagramm-wiederherstellen" tabindex="-1">Diagramm wiederherstellen <a class="header-anchor" href="#diagramm-wiederherstellen" aria-label="Permalink to “Diagramm wiederherstellen”">​</a></h2><p>Mit der Berechtigung <code>entity:restore</code> listet der Schalter <em>Gelöschte anzeigen</em> auf der Seite <em>Diagramme</em> die gelöschten Diagramme mit Zeitpunkt und Person des Löschens. Wähle <em>Wiederherstellen</em>, um ein Diagramm samt seinen Einträgen im Navigationsbaum zurückzuholen. Hat inzwischen ein anderes Diagramm seinen Namen bekommen, meldet die Seite das, und das Diagramm bleibt gelöscht; benenne zuerst das andere Diagramm um.</p><h2 id="viewpoint-loschen" tabindex="-1">Viewpoint löschen <a class="header-anchor" href="#viewpoint-loschen" aria-label="Permalink to “Viewpoint löschen”">​</a></h2><p>Diagramme können ohne ihren Viewpoint nicht bestehen. Löschst du einen Viewpoint, den Diagramme nutzen, werden sie mit ihm <strong>endgültig</strong> gelöscht, auch die bereits gelöschten; die Entitäten bleiben. Die Bestätigung nennt die Anzahl der Diagramme, die gelöscht werden (siehe <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). Dasselbe geschieht, wenn eine neue Version eines <a href="./../administration/metamodel-packages">Metamodell-Pakets</a> einen systemdefinierten Viewpoint nicht mehr enthält.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p>Die Diagramme sind über <code>/diagrams</code> verfügbar (siehe die <a href="./../api/">API-Referenz</a>):</p><ul><li><code>GET /diagrams</code> listet die Diagramme nach Namen. <code>q</code> ist ein Namensteil (höchstens 200 Zeichen), <code>pageSize</code> ist 1 bis 200 (Standard 50), und <code>page</code> beginnt bei 0. Die Antwort enthält <code>nextCursor</code>; sende ihn als <code>cursor</code> zusammen mit <code>page</code> um 1 erhöht, um fortzufahren. Ein Cursor einer anderen Abfrage wird mit 400 abgelehnt, das <code>cursor</code> nennt.</li><li><code>POST /diagrams</code> legt ein Diagramm aus <code>name</code>, <code>description</code> und <code>viewpointId</code> an; <code>GET /diagrams/{id}</code> liest es; <code>PUT /diagrams/{id}</code> ändert <code>name</code> und <code>description</code> (eine <code>viewpointId</code> wird ignoriert); <code>DELETE /diagrams/{id}</code> löscht es. Jede Änderung braucht den Header <code>If-Match</code> mit der gelesenen Version (<code>&quot;3&quot;</code>); ohne ihn lautet die Antwort 428, mit einer anderen Version 412. Die Antworten tragen die neue Version als <code>ETag</code>.</li><li><code>GET /diagrams/deleted</code> listet die gelöschten Diagramme, und <code>POST /diagrams/{id}/restore</code> mit <code>If-Match</code> stellt eines wieder her; beides braucht <code>entity:restore</code>. Ein Diagramm, das nicht gelöscht ist, antwortet mit 409 (<code>urn:oea:problem:diagram-not-deleted</code>).</li><li>Ein vergebener Name antwortet mit 422 und dem Problemtyp <code>urn:oea:problem:diagram-name-taken</code>; sonstige ungültige Eingaben antworten mit 422 und nennen das Feld in <code>invalidFields</code> (<code>name</code>, <code>description</code> oder <code>viewpointId</code>). Ein unbekanntes oder gelöschtes Diagramm antwortet mit 404.</li><li>Jede Änderung steht im Audit-Trail als <code>diagram.created</code>, <code>diagram.updated</code>, <code>diagram.deleted</code> oder <code>diagram.restored</code>.</li><li><code>GET /views/diagrams/{id}</code> liefert die Ansicht eines Diagramms: das Diagramm mit seiner Version (<code>ETag</code>), seinen Viewpoint mit den wirksamen Standardgrößen und die Formen in Zeichenreihenfolge (die letzte liegt oben) mit Form-ID, Entität, Position und Größe in pt sowie <code>missingMandatory</code>, den Namen der Pflichteigenschaften ohne Wert. Formen einer gelöschten Entität fehlen.</li><li><code>PUT /views/diagrams/{id}</code> speichert das Layout mit <code>If-Match</code>: alle <code>shapes</code> in Zeichenreihenfolge (<code>id</code>, genau eines von <code>entityId</code> und <code>newEntityKey</code>, <code>x</code>, <code>y</code>, <code>width</code>, <code>height</code>) und die <code>newEntities</code> (<code>key</code>, <code>metatypeId</code>, <code>name</code>), auf die die Formen mit <code>newEntityKey</code> verweisen. Das Speichern ist atomar und erhöht die Version. Neue Entitäten werden wie Entitäten des Batch-Schreibens angelegt (<code>entity.created</code>), eine Entität mit fehlender Pflichteigenschaft wird aber unvollständig angelegt statt abgelehnt. Grenzen: 2000 Formen, 500 neue Entitäten, Positionen innerhalb von ±100 000 pt, Größen 1 bis 2000 pt, höchstens zwei Nachkommastellen, ein Body von 2 MB; Verstöße werden mit 400 oder 413 beantwortet. Eine fehlerhafte Form oder neue Entität wird mit 422 samt <code>invalidFields</code> und <code>errors</code> beantwortet (zum Beispiel <code>shapes[3].entityId</code> oder <code>newEntities[1].name</code>); dann wird nichts gespeichert. Auch eine Form-ID eines anderen Diagramms wird abgelehnt.</li><li><code>GET /views/diagrams/{id}/entities</code> durchsucht die Entitäten, die der Viewpoint erlaubt (<code>q</code> bis 255 Zeichen, <code>metatypeId</code>, <code>page</code>, <code>pageSize</code> 1 bis 200); ein Metatyp, den der Viewpoint nicht erlaubt, wird mit 422 und <code>metatypeId</code> beantwortet.</li><li>Jedes gespeicherte Layout steht im Audit-Trail als <code>diagram.layout-saved</code> mit den Anzahlen hinzugefügter, geänderter und entfernter Formen und angelegter Entitäten.</li><li><code>GET /views/diagrams/{id}/entities/{entityId}</code> liefert die Details einer Entität, die eine Form des Diagramms zeigt: <code>name</code>, <code>description</code>, <code>metatype</code>, <code>version</code>, die Werte in <code>properties</code> (ein Wert, den du nicht lesen darfst, hat <code>redacted: true</code>), in <code>fields</code> für jede zugeordnete Eigenschaft, ob du sie lesen (<code>readable</code>) und ändern (<code>writable</code>) darfst, und <code>missingMandatory</code>. Eine Entität ohne Form im Diagramm, eine gelöschte Entität und ein gelöschtes Diagramm antworten mit 404. Datentypen, Aufzählungswerte und Grenzen der Eigenschaften stammen vom Metatyp (<code>GET /metamodel/metatypes/{id}</code>).</li><li><code>GET /views/diagrams/{id}/reference-targets?propertyDefId=…</code> listet die Entitäten, auf die eine Referenzeigenschaft zeigen darf: die Entitäten genau des referenzierten Typs, nach Namen (<code>q</code> bis 255 Zeichen, <code>page</code>, <code>pageSize</code> 1 bis 200). Eine Eigenschaft, die keine Referenzeigenschaft ist, antwortet mit 422 und nennt <code>propertyDefId</code>.</li><li><code>PUT /views/diagrams/{id}</code> trägt auch <code>entityUpdates</code>, höchstens 500: Jede nennt eine <code>entityId</code>, die eine Form derselben Anfrage zeigt (einmal), die gelesene <code>expectedVersion</code> (mindestens 1) und optional <code>name</code> (nicht leer, bis 255 Zeichen), <code>description</code> (bis 2000) und <code>properties</code> (<code>propertyDefId</code> und <code>value</code>; ein leerer <code>value</code> entfernt den Wert). Nicht genannte Felder und Eigenschaften behalten ihren Wert. Die Änderungen werden in derselben Transaktion wie das Layout geschrieben, mit den Prüfungen und dem Audit einer Batch-Änderung (<code>entity.updated</code>); eine geänderte Entität braucht ihre Pflichtwerte (422 <code>MANDATORY_MISSING</code> auf <code>entityUpdates[i].properties</code>), und eine eingeschränkte Eigenschaft ohne Schreibzugriff führt für das ganze Speichern zu 403. Ein Eintrag von <code>newEntities</code> kann ebenfalls <code>description</code> und <code>properties</code> tragen. Eine Entität mit anderer aktueller Version antwortet mit 409 und dem Problemtyp <code>urn:oea:problem:entity-version-conflict</code> samt <code>conflicts</code> (<code>entityId</code> und <code>currentVersion</code> jeder veralteten Entität); eine Entität mit einem offenen Punkt einer Lösung antwortet mit 409 <code>urn:oea:problem:entity-blocked</code>. Es wird dann nichts geändert. Die Batch-API (<code>POST /entities/batch</code>) schreibt weiterhin ohne Version.</li></ul>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};